def get_method_id(name: str) -> int:
    """Return the TL ctor id for a method name, or raise KeyError."""
    if name not in METHODS:
        raise KeyError(f"Unknown method: {name}")
    return METHODS[name]


def get_constructor_id(predicate: str) -> int:
    """Return the TL ctor id for a constructor predicate, or raise KeyError."""
    if predicate not in CONSTRUCTORS:
        raise KeyError(f"Unknown constructor: {predicate}")
    return CONSTRUCTORS[predicate]
